/// <summary>
///    Sets the invoice address fields on the packing slip journal to be able to print both delivery
///    address and invoice address.
/// </summary>
/// <param name="_salesTable">
///    The sales order header to post.
/// </param>
void  setInvoiceAddress(SalesTable _salesTable)
{
    CustInvoiceJour custInvoiceJour;
    LogisticsPostalAddress deliveryAddress;

    next setInvoiceAddress(_salesTable);

    custInvoiceJour.OrderAccount = _salesTable.CustAccount;
    custInvoiceJour.InvoiceAccount = _salesTable.InvoiceAccount;
    custInvoiceJour.DeliveryPostalAddress = _salesTable.DeliveryPostalAddress;

    if (_salesTable.ProjId)
    {
        custInvoiceJour.setInvoiceAddressFromProject(_salesTable.ProjId);
    }
    else
    {
        custInvoiceJour.setInvoiceAddress(_salesTable);
    }

    if (!custInvoiceJour.InvoicePostalAddress)
    {
        if (_salesTable.DeliveryPostalAddress)
        {
            deliveryAddress = _salesTable.deliveryAddress();
            this.InvoicingName           = deliveryAddress.avaName();
        }
    }
}

/// <summary>
/// Extension of method initFromSalesTable
/// </summary>
/// <param name = "_salesTable">SalesTable</param>
void  initFromSalesTable(SalesTable _salesTable)
{
    next initFromSalesTable(_salesTable);

    this.AVASalesGroup                  = _salesTable.SalesGroup;
    this.AVAInventSiteId                = _salesTable.InventSiteId;
    this.KCS_PurchRefDate               = _salesTable.KCS_PurchRefDate;
    this.AVAVATNum                      = _salesTable.VATNum;
    this.AVADlvResponsible              = _salesTable.AVADlvResponsible;
    this.AVAShipCarrierDeliveryContact  = _salesTable.AVAShipCarrierDeliveryContact;
    this.AVAShipCarrierDeliveryMobile   = _salesTable.AVAShipCarrierDeliveryMobile;
    this.NDX_ShipCarrierDeliveryFax     = _salesTable.NDX_ShipCarrierDeliveryFax;
    this.NDX_ShipCarrierDeliveryPhone   = _salesTable.NDX_ShipCarrierDeliveryPhone;
    this.AVARicoCustomer                = _salesTable.AVARicoCustomer;

    this.DeliveryName       = this.avaUpdateDeliveryName(_salesTable);
}

/// <summary>
/// AVA
/// </summary>
/// <param name = "_salesTable">SalesTable</param>
/// <returns>CustName</returns>
public CustName avaUpdateDeliveryName(SalesTable _salesTable)
{
    LogisticsPostalAddress logisticsPostalAddressLoc = _salesTable.deliveryAddress();
    CustName avaNameLoc = _salesTable.DeliveryName;

    if(logisticsPostalAddressLoc.NDXLogisticsLocationName1)
    {
        avaNameLoc = logisticsPostalAddressLoc.NDXLogisticsLocationName1;
    }

    if(logisticsPostalAddressLoc.NDXLogisticsLocationName2)
    {
        if(avaNameLoc != '')
        {
            avaNameLoc += '\n';
        }

        avaNameLoc += logisticsPostalAddressLoc.NDXLogisticsLocationName2;
    }

    if(logisticsPostalAddressLoc.NDXLogisticsLocationName3)
    {
        if(avaNameLoc != '')
        {
            avaNameLoc += '\n';
        }

        avaNameLoc += '\n' + logisticsPostalAddressLoc.NDXLogisticsLocationName3;
    }

    return avaNameLoc;
}

/// <summary>
/// AVA
/// </summary>
/// <param name = "_salesTable">SalesTable</param>
/// <returns>CustName</returns>
public CustName avaUpdateInvoicingName(SalesTable _salesTable)
{
    LogisticsPostalAddress logisticsPostalAddressLoc = LogisticsPostalAddress::findRecId(_salesTable.invoicePostalAddressRecId());
    CustName avaNameLoc = _salesTable.invoiceName();

    if(logisticsPostalAddressLoc.NDXLogisticsLocationName1)
    {
        avaNameLoc = logisticsPostalAddressLoc.NDXLogisticsLocationName1;
    }

    if(logisticsPostalAddressLoc.NDXLogisticsLocationName2)
    {
        if(avaNameLoc != '')
        {
            avaNameLoc += '\n';
        }

        avaNameLoc += logisticsPostalAddressLoc.NDXLogisticsLocationName2;
    }

    if(logisticsPostalAddressLoc.NDXLogisticsLocationName3)
    {
        if(avaNameLoc != '')
        {
            avaNameLoc += '\n';
        }

        avaNameLoc += '\n' + logisticsPostalAddressLoc.NDXLogisticsLocationName3;
    }

    return avaNameLoc;
}

/// <summary>
/// checks if the related salesTable has a PurchTable record connected to an intercompany sales order and returns it
/// </summary>
/// <returns>SalesTable</returns>
public SalesTable avaIntercompanySalesTable()
{
    PurchTable avaRefPurchTable = this.salesTable().referencePurchTable();
    SalesTable avaInterCompanySalesTable;

    changeCompany(avaRefPurchTable.InterCompanyCompanyId)
    {
        avaInterCompanySalesTable = SalesTable::find(avaRefPurchTable.InterCompanySalesId);
    }        

    return avaInterCompanySalesTable;
}

/// <summary>
/// AVA_008475_CustCredit
/// </summary>
void avaSetEstimate()
{
    SalesTable  locSalesTable;

    if (CustTable::find(this.InvoiceAccount).MandatoryCreditLimit)
    {
        locSalesTable = this.salesTable(true);
        if (locSalesTable.setEstimate())
        {
            locSalesTable.update();
        }
    }
}

public void insert()
{
    next insert();
    this.avaSetEstimate();
}
